namespace StudentManagement.API.Models;

/// <summary>
/// Core Student entity stored in the in-memory data store.
/// This class is never exposed directly to the client - DTOs are used instead.
/// </summary>
public class Student
{
    /// <summary>Unique identifier, auto-generated by the service.</summary>
    public int Id { get; set; }

    /// <summary>Full name of the student.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Email address of the student.</summary>
    public string Email { get; set; } = string.Empty;

    /// <summary>Course the student is enrolled in.</summary>
    public string Course { get; set; } = string.Empty;

    /// <summary>Age of the student in years.</summary>
    public int Age { get; set; }

    /// <summary>Date and time (UTC) when the record was created.</summary>
    public DateTime EnrolledOn { get; set; }
}
